public func ensureMainThread<T>(execute work: @escaping @MainActor () -> T) -> T? {
    if Thread.isMainThread {
        return MainActor.assumeIsolated {
            return work()
        }
    } else {
        DispatchQueue.main.async {
            _ = work()
        }
        return nil
    }
