fn generate_github_mirror_url_from_base(github_url: &str) -> Option<String> {
  std::env::var("TAURI_BUNDLER_TOOLS_GITHUB_MIRROR")
    .ok()
    .and_then(|cdn| Url::parse(&cdn).ok())
    .map(|cdn| {
      cdn.to_string()
    })
}

let response = ureq::get(url).call().map_err(Box::new)?;
let mut bytes = Vec::new();
response.into_body().into_reader().read_to_end(&mut bytes)?;
std::fs::write(&file_path, bytes)?;

if lock.is_some() && !crate_lock_packages.is_empty() {
  let lock_version = crate_lock_packages
    .iter()
    .map(|p| p.version.clone())
    .collect::<Vec<String>>()
    .join(", ");

  if !lock_version.is_empty() {
    version.lock_version = Some(lock_version);
  }
}

